import{_ as n,o as t,c as i,a2 as s}from"./chunks/framework.vLhlLNVn.js";const m=JSON.parse('{"title":"Segmente und Synchronisation","description":"","frontmatter":{"order":4,"adapter":"wled","editLink":"https://github.com/DrozmotiX/ioBroker.wled/edit/main/docs/de/04.fehlerbehebung/04.segmente-und-synchronisation.md"},"headers":[],"relativePath":"de/adapter/wled/fehlerbehebung/segmente-und-synchronisation.md","filePath":"de/adapter/wled/fehlerbehebung/segmente-und-synchronisation.md","lastUpdated":null}'),r={name:"de/adapter/wled/fehlerbehebung/segmente-und-synchronisation.md"};function a(d,e,l,o,c,h){return t(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="segmente-und-synchronisation" tabindex="-1">Segmente und Synchronisation <a class="header-anchor" href="#segmente-und-synchronisation" aria-label="Permalink to &quot;Segmente und Synchronisation&quot;">​</a></h1><p><a id="segment-states-not-appear-remain"></a></p><h2 id="warum-erscheinen-segment-datenpunkte-nicht-oder-bleiben-nach-dem-loschen-in-wled-bestehen" tabindex="-1">Warum erscheinen Segment-Datenpunkte nicht oder bleiben nach dem Löschen in WLED bestehen? <a class="header-anchor" href="#warum-erscheinen-segment-datenpunkte-nicht-oder-bleiben-nach-dem-loschen-in-wled-bestehen" aria-label="Permalink to &quot;Warum erscheinen Segment-Datenpunkte nicht oder bleiben nach dem Löschen in WLED bestehen?&quot;">​</a></h2><p><strong>Kurz:</strong> Bis v0.9.2 zieht der Adapter Segmente nur teilweise nach: Die Datenpunkte eines neuen Segments erscheinen mit der nächsten Aktualisierung, der Ordner dazu erst nach einem Neustart des Adapters. In WLED gelöschte Segmente bleiben im Objektbaum stehen, bis du sie selbst löschst. Ab v0.9.3 legt der Adapter neue Segmente sofort an und löscht entfernte von selbst.</p><h3 id="bis-v0-9-2" tabindex="-1">Bis v0.9.2 <a class="header-anchor" href="#bis-v0-9-2" aria-label="Permalink to &quot;Bis v0.9.2&quot;">​</a></h3><ul><li><strong>Neues Segment in WLED:</strong> Der Adapter schreibt die Werte des Segments bei der nächsten Aktualisierung in den Objektbaum. Den Ordner <code>seg.&lt;Segment&gt;</code> mit dem Namen „Segment …“ legt er aber nur beim Verbinden mit dem Gerät an. Nach einem Neustart des Adapters ist alles vollständig.</li><li><strong>Gelöschtes Segment in WLED:</strong> Der Ordner <code>seg.&lt;Segment&gt;</code> und seine Datenpunkte bleiben stehen und zeigen die letzten Werte. Der Adapter löscht sie nicht.</li><li><strong>Nummern mit Lücken:</strong> Der Adapter nummeriert die Ordner nach der Reihenfolge, in der WLED die Segmente meldet, nicht nach ihrer Nummer in WLED. Hat WLED die Segmente 0 und 2, heißen die Ordner <code>seg.0</code> und <code>seg.1</code>. Schreibst du in <code>seg.1</code>, geht der Befehl an Segment 1 in WLED, nicht an Segment 2.</li></ul><p>So räumst du auf:</p><ol><li>Öffne im Admin den Reiter „Objekte“ und such <code>wled.0.&lt;Gerät&gt;.seg</code>.</li><li>Vergleich die Ordner mit den Segmenten in der WLED-Oberfläche.</li><li>Lösch die Ordner, die es in WLED nicht mehr gibt, samt Inhalt.</li><li>Starte die Adapter-Instanz neu, damit die Ordner neu angelegt werden, die noch fehlen.</li></ol><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Löschst du ein Segment über <code>sendTo</code> mit <code>deleteSegment</code>, entfernt der Adapter den Ordner gleich mit. Das Aufräumen von Hand brauchst du nur, wenn du das Segment in der WLED-Oberfläche gelöscht hast.</p></div><p><strong>Ab v0.9.3:</strong> Der Adapter gleicht die Segmente bei jeder Aktualisierung ab (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/909" target="_blank" rel="noreferrer">#909</a>):</p><ul><li>Ein neues Segment bekommt sofort seinen Ordner.</li><li>Ein in WLED gelöschtes Segment löscht er aus dem Objektbaum und schreibt <code>Segment &lt;Segment&gt; removed on device &lt;MAC&gt;, deleting its states</code> ins Log.</li><li>Die Ordner heißen nach der Segmentnummer in WLED. Lücken bleiben Lücken, <code>seg.2</code> ist also immer Segment 2.</li></ul><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Nach dem Update auf v0.9.3 können sich bei Geräten mit Lücken in den Segmentnummern die Ordnernamen ändern. Skripte und VIS-Ansichten, die <code>seg.1</code> meinten, aber Segment 2 steuerten, musst du dann auf <code>seg.2</code> umstellen.</p></div><p><strong>Siehe auch:</strong> <a href="./../anleitungen/segmente-und-einzelne-leds#create-delete-segments-iobroker-preset">Segmente aus ioBroker anlegen und löschen</a> · <a href="./verbindung-und-start#adapter-stop-working-after-wled">Adapter funktioniert nach WLED-Update nicht mehr, oder Segmente nur an einem Gerät</a></p><p><a id="not-segment-mirror-seg-n"></a></p><h2 id="warum-lasst-sich-die-segment-spiegelung-seg-n-mi-nicht-setzen" tabindex="-1">Warum lässt sich die Segment-Spiegelung (seg.N.mi) nicht setzen? <a class="header-anchor" href="#warum-lasst-sich-die-segment-spiegelung-seg-n-mi-nicht-setzen" aria-label="Permalink to &quot;Warum lässt sich die Segment-Spiegelung (seg.N.mi) nicht setzen?&quot;">​</a></h2><p><strong>Kurz:</strong> Bis v0.9.2 ist <code>seg.&lt;Segment&gt;.mi</code> nur lesbar. Der Adapter reagiert nicht, wenn du hineinschreibst. Als Umweg schickst du <code>{&quot;seg&quot;:[{&quot;id&quot;:0,&quot;mi&quot;:true}]}</code> an <code>wled.0.&lt;Gerät&gt;.action</code>. Ab v0.9.3 lässt sich <code>mi</code> direkt schreiben.</p><p><code>mi</code> spiegelt ein Segment: Die zweite Hälfte zeigt den Effekt der ersten Hälfte spiegelverkehrt. Der Adapter legt den Datenpunkt an, weil WLED ihn meldet. Bis v0.9.2 fehlt in seiner Beschreibung aber die Freigabe zum Schreiben. Darum abonniert der Adapter ihn nicht, und ein geschriebener Wert kommt nie bei WLED an.</p><h3 id="umweg-bis-v0-9-2" tabindex="-1">Umweg bis v0.9.2 <a class="header-anchor" href="#umweg-bis-v0-9-2" aria-label="Permalink to &quot;Umweg bis v0.9.2&quot;">​</a></h3><ol><li>Öffne im Objektbaum <code>wled.0.&lt;Gerät&gt;.action</code>.</li><li>Schreib <code>{&quot;seg&quot;:[{&quot;id&quot;:0,&quot;mi&quot;:true}]}</code> hinein. Die <code>0</code> ersetzt du durch die Nummer deines Segments. Mit <code>false</code> schaltest du die Spiegelung wieder aus.</li><li>Kurz danach zeigt <code>seg.0.mi</code> den neuen Wert.</li></ol><p>Im Skript:</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setState</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;wled.0.&lt;Gerät&gt;.action&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">JSON</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">stringify</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ seg: [{ id: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, mi: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }] }));</span></span></code></pre></div><p>Die Spiegelung kannst du auch in der WLED-Oberfläche einstellen und in einem Preset speichern. Dann reicht es, das Preset über <code>ps</code> zu laden.</p><p><strong>Ab v0.9.3:</strong> <code>seg.&lt;Segment&gt;.mi</code> ist ein Wahrheitswert und lässt sich direkt schreiben, zum Beispiel mit <code>setState(&#39;wled.0.&lt;Gerät&gt;.seg.0.mi&#39;, true)</code> (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/918" target="_blank" rel="noreferrer">#918</a>).</p><p><strong>Siehe auch:</strong> <a href="./../anleitungen/befehle-an-wled#send-complete-json-command-wled">Kompletten JSON-Befehl senden</a> · <a href="./../referenz/datenpunkte#individual-wled-states-mean">Was bedeuten die einzelnen WLED-Datenpunkte?</a></p><p><a id="one-wled-device-take-over"></a></p><h2 id="warum-ubernimmt-ein-wled-gerat-die-einstellungen-eines-anderen" tabindex="-1">Warum übernimmt ein WLED-Gerät die Einstellungen eines anderen? <a class="header-anchor" href="#warum-ubernimmt-ein-wled-gerat-die-einstellungen-eines-anderen" aria-label="Permalink to &quot;Warum übernimmt ein WLED-Gerät die Einstellungen eines anderen?&quot;">​</a></h2><p><strong>Kurz:</strong> Das macht WLED selbst, nicht der Adapter. WLED-Geräte gleichen sich über UDP-Sync im Netzwerk ab: Ändert sich eins, schickt es seinen Zustand an alle anderen, und wer empfängt, übernimmt ihn. Das schaltest du im Gerät aus, das nicht folgen soll: In der WLED-Oberfläche unter „Config“, „Sync Interfaces“ nimmst du bei „Sync groups“ die Haken bei „Receive“ heraus.</p><p>UDP-Sync ist in WLED ab Werk eingeschaltet. Die Werte, die ein Gerät von einem anderen übernimmt, kommen danach wie jede andere Änderung als Rückmeldung beim Adapter an. Darum sieht es in ioBroker so aus, als hätte der Adapter das zweite Gerät umgestellt.</p><h3 id="dauerhaft-ausschalten-je-gerat" tabindex="-1">Dauerhaft ausschalten, je Gerät <a class="header-anchor" href="#dauerhaft-ausschalten-je-gerat" aria-label="Permalink to &quot;Dauerhaft ausschalten, je Gerät&quot;">​</a></h3><ol><li>Öffne die Weboberfläche des Geräts, das <strong>nicht</strong> folgen soll, unter <code>http://192.168.x.y</code>.</li><li>Geh zu „Config“, „Sync Interfaces“.</li><li>Nimm unter „Sync groups“ in der Zeile „Receive“ alle Haken heraus.</li><li>Soll das Gerät auch selbst nichts an andere schicken, nimm die Haken in der Zeile „Send“ ebenfalls heraus.</li><li>Speichere. Ändere danach ein anderes Gerät: Das hier muss so bleiben, wie es ist.</li></ol><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Sollen nur bestimmte Geräte zusammen laufen, nutze die Gruppen 1 bis 8: Ein Gerät übernimmt nur Meldungen aus den Gruppen, die bei ihm unter „Receive“ angehakt sind.</p></div><h3 id="aus-iobroker-steuern" tabindex="-1">Aus ioBroker steuern <a class="header-anchor" href="#aus-iobroker-steuern" aria-label="Permalink to &quot;Aus ioBroker steuern&quot;">​</a></h3><p>Unter <code>wled.0.&lt;Gerät&gt;.udpn</code> liegen die Werte für UDP-Sync. Sie gelten nur bis zum nächsten Neustart von WLED. Danach gilt wieder, was in den Einstellungen des Geräts steht.</p><table tabindex="0"><thead><tr><th>Datenpunkt</th><th>Wirkung</th></tr></thead><tbody><tr><td><code>udpn.send</code></td><td><code>false</code>: das Gerät schickt bei Änderungen nichts an andere</td></tr><tr><td><code>udpn.recv</code></td><td>zeigt nur an, ob das Gerät empfängt. WLED nimmt Schreibzugriffe darauf nicht an</td></tr><tr><td><code>udpn.rgrp</code></td><td>Empfangsgruppen als Zahl, nur lesbar. <code>0</code> heißt: empfängt nichts</td></tr><tr><td><code>udpn.nn</code></td><td>gilt nur für den Befehl, mit dem es mitgeschickt wird: diese Änderung nicht weitergeben</td></tr></tbody></table><p>Um den Empfang aus ioBroker abzuschalten, schickst du <code>{&quot;udpn&quot;:{&quot;rgrp&quot;:0}}</code> an <code>wled.0.&lt;Gerät&gt;.action</code>. Um nur einen einzelnen Befehl nicht weiterzugeben, schickst du <code>nn</code> mit, zum Beispiel <code>{&quot;on&quot;:true,&quot;udpn&quot;:{&quot;nn&quot;:true}}</code>.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Den Datenpunkt <code>udpn.nn</code> allein zu setzen bringt nichts: Der Adapter schickt ihn als eigenen Befehl ohne Änderung. <code>nn</code> wirkt nur zusammen mit der Änderung in einem Befehl über <code>action</code>.</p></div><p><strong>Siehe auch:</strong> <a href="./../referenz/datenpunkte#use-udp-sync-state-udpn">Wie nutze ich den Datenpunkt für UDP-Sync (udpn)?</a> · <a href="./../anleitungen/befehle-an-wled#send-complete-json-command-wled">Kompletten JSON-Befehl senden</a></p>',37)])])}const g=n(r,[["render",a]]);export{m as __pageData,g as default};
